  model: 'claude-sonnet-5',
  max_tokens: 4000,
  tools: [{"name":"write_article","description":"Write the full grounded article for the chosen angle.","input_schema":{"type":"object","required":["title","body_markdown","secondary_keywords"],"properties":{"title":{"type":"string"},"body_markdown":{"type":"string"},"secondary_keywords":{"type":"array","items":{"type":"string"}}}}}],
