const err = $json.error || {};
const message = (err.message || JSON.stringify(err) || 'Unknown Claude API error').slice(0, 500);
return [{ json: { requestId: $('Config').first().json.request_id, message } }];

const c = $json.criteria || [];
const floor = (name, f) => { const crit = c.find(x => x.name.toLowerCase().includes(name)); return crit ? crit.score < f : false; };
const hardBlock = $json.hard_block_triggered || floor('topic', 15) || floor('grounding', 15) || floor('factual', 15) || floor('consistency', 15);
const score = $json.overall_score;
let decision;
if (hardBlock) { decision = score < 60 ? 'reject' : 'revise'; }
else if (score >= 85) { decision = 'pass'; }
else if (score >= 60) { decision = 'revise'; }
else { decision = 'reject'; }
return [{ json: { ...$json, hardBlock, decision } }];

